import { useEffect, useRef, useState, type SubmitEvent } from 'react';
import { Button, Container, Group, Stack, Stepper, Title } from '@mantine/core';
import { useForm, type FormErrors } from '@mantine/form';
import { notifications } from '@mantine/notifications';
import { AvailabilityStep } from './AvailabilityStep';
import { ExperienceStep } from './ExperienceStep';
import { PersonalStep } from './PersonalStep';
import { ReviewStep } from './ReviewStep';
import { StepErrorSummary } from './StepErrorSummary';
import type { JobApplication, JobApplicationValues } from './types';
import { getStepPaths, INITIAL_VALUES, REVIEW_STEP, RULES, STEPS } from './validation';

interface JobApplicationFormProps {
  onSubmit?: (application: JobApplication) => void | Promise<void>;
}

export function JobApplicationForm({ onSubmit }: JobApplicationFormProps) {
  const [active, setActive] = useState(0);
  const [furthest, setFurthest] = useState(0);
  const [showSummary, setShowSummary] = useState(false);
  const addPositionRef = useRef<HTMLButtonElement>(null);
  const pendingFocus = useRef<string | null>(null);

  const form = useForm<JobApplicationValues>({
    name: 'job-application',
    initialValues: INITIAL_VALUES,
    validateInputOnBlur: ['email', 'linkedin'],
    validate: RULES,
  });

  const focusField = (path: string) => {
    if (path === 'positions') {
      addPositionRef.current?.focus();
      return;
    }
    // Radio.Group and picker inputs put data-path on a wrapper, focus the control inside it
    const node = form.getInputNode(path);
    const control = node?.matches('input, textarea, button')
      ? node
      : node?.querySelector<HTMLElement>('input, textarea, button');
    (control ?? node)?.focus();
  };

  // Fields of a step are mounted only after the step renders
  useEffect(() => {
    if (pendingFocus.current) {
      focusField(pendingFocus.current);
      pendingFocus.current = null;
    }
  });

  const showStepWithError = (step: number, path: string) => {
    setShowSummary(true);
    if (step === active) {
      focusField(path);
    } else {
      pendingFocus.current = path;
      setActive(step);
    }
  };

  // Every field of the step is validated so that all of its errors show at once
  const validateStep = (step: number) => {
    const invalidPaths = getStepPaths(step, form.getValues()).filter(
      (path) => form.validateField(path).hasError
    );
    return invalidPaths[0] ?? null;
  };

  const goTo = (target: number) => {
    for (let step = active; step < target; step += 1) {
      const invalidPath = validateStep(step);
      if (invalidPath) {
        showStepWithError(step, invalidPath);
        return;
      }
    }
    setShowSummary(false);
    setActive(target);
    setFurthest((current) => Math.max(current, target));
  };

  const handleSubmit = async ({
    phoneDisplay: _phoneDisplay,
    ...application
  }: JobApplicationValues) => {
    await onSubmit?.(application);
    notifications.show({
      title: 'Application submitted',
      message: `${application.firstName} ${application.lastName} · ${application.currentTitle}`,
    });
    form.reset();
    setShowSummary(false);
    setActive(0);
    setFurthest(0);
  };

  const handleErrors = (errors: FormErrors) => {
    const values = form.getValues();
    for (let step = 0; step < REVIEW_STEP; step += 1) {
      const invalidPath = getStepPaths(step, values).find((path) => errors[path]);
      if (invalidPath) {
        showStepWithError(step, invalidPath);
        return;
      }
    }
  };

  const submit = form.onSubmit(handleSubmit, handleErrors);

  // Enter in a field of an earlier step moves to the next step instead of submitting
  const handleFormSubmit = (event: SubmitEvent<HTMLFormElement>) => {
    if (active === REVIEW_STEP) {
      submit(event);
    } else {
      event.preventDefault();
      goTo(active + 1);
    }
  };

  const stepErrors = showSummary
    ? getStepPaths(active, form.getValues())
        .filter((path) => form.errors[path])
        .map((path) => ({ path, message: form.errors[path] }))
    : [];

  const stepContent = [
    <PersonalStep key="personal" form={form} />,
    <ExperienceStep key="experience" form={form} addPositionRef={addPositionRef} />,
    <AvailabilityStep key="availability" form={form} />,
    <ReviewStep key="review" form={form} onEdit={goTo} />,
  ];

  return (
    <Container size="sm" py="xl">
      <Title order={2} c="var(--mantine-color-bright)" mb="xl">
        Job application
      </Title>
      <form onSubmit={handleFormSubmit} noValidate>
        <Stepper active={active} onStepClick={goTo}>
          {STEPS.map((label, index) => (
            <Stepper.Step
              key={label}
              label={label}
              allowStepSelect={index <= furthest && index !== active}
            >
              <Stack mt="xl">
                <StepErrorSummary errors={stepErrors} onSelect={focusField} />
                {stepContent[index]}
              </Stack>
            </Stepper.Step>
          ))}
        </Stepper>

        <Group justify={active > 0 ? 'space-between' : 'flex-end'} mt="xl">
          {active > 0 && (
            <Button variant="default" onClick={() => goTo(active - 1)}>
              Back
            </Button>
          )}
          <Button
            type="submit"
            loading={form.submitting}
            // Keeps focus in the field until the click completes, so its blur error does not shift the button
            onMouseDown={(event) => event.preventDefault()}
          >
            {active === REVIEW_STEP ? 'Submit application' : 'Next'}
          </Button>
        </Group>
      </form>
    </Container>
  );
}

import { NumberInput, Radio, Stack, Text, Textarea } from '@mantine/core';
import { DatePickerInput } from '@mantine/dates';
import type { JobApplicationFormType } from './types';
import { NOTES_LIMIT, WORK_MODES } from './validation';

export function AvailabilityStep({ form }: { form: JobApplicationFormType }) {
  const notes = form.useWatchValue('notes');

  return (
    <Stack>
      <DatePickerInput
        label="Earliest start date"
        placeholder="Pick a date"
        valueFormat="MMMM D, YYYY"
        minDate={new Date()}
        withAsterisk
        maw={320}
        {...form.getInputProps('startDate')}
      />
      <NumberInput
        label="Expected salary"
        placeholder="Annual salary in USD"
        prefix="$"
        thousandSeparator=","
        allowNegative={false}
        allowDecimal={false}
        max={10_000_000}
        hideControls
        maw={320}
        {...form.getInputProps('salary')}
      />
      <Radio.Group label="Work arrangement" withAsterisk {...form.getInputProps('workMode')}>
        <Stack gap="xs" mt="xs">
          {WORK_MODES.map((mode) => (
            <Radio key={mode.value} value={mode.value} label={mode.label} />
          ))}
        </Stack>
      </Radio.Group>
      <Textarea
        label="Notes"
        placeholder="Anything else we should know"
        autosize
        minRows={3}
        maxRows={8}
        maxLength={NOTES_LIMIT}
        bottomSection={
          <Text size="xs" ta="right" c={notes.length >= NOTES_LIMIT ? 'red' : undefined}>
            {notes.length}/{NOTES_LIMIT}
          </Text>
        }
        {...form.getInputProps('notes')}
      />
    </Stack>
  );
}

import type { Ref } from 'react';
import { Button, Group, Input, NumberInput, Stack, Text, TextInput } from '@mantine/core';
import { PositionRow } from './PositionRow/PositionRow';
import type { JobApplicationFormType } from './types';
import { createPosition } from './validation';

interface ExperienceStepProps {
  form: JobApplicationFormType;
  addPositionRef: Ref<HTMLButtonElement>;
}

export function ExperienceStep({ form, addPositionRef }: ExperienceStepProps) {
  const positions = form.useWatchValue('positions');

  return (
    <Stack>
      <TextInput
        label="Current title"
        placeholder="Current title"
        withAsterisk
        {...form.getInputProps('currentTitle')}
      />
      <NumberInput
        label="Years of experience"
        placeholder="Years of experience"
        min={0}
        max={50}
        clampBehavior="strict"
        allowNegative={false}
        allowDecimal={false}
        withAsterisk
        maw={240}
        {...form.getInputProps('yearsOfExperience')}
      />
      <Stack gap="xs">
        <Input.Label required labelElement="div">
          Previous positions
        </Input.Label>
        {positions.length > 0 ? (
          positions.map((position, index) => (
            <PositionRow key={position.id} form={form} index={index} />
          ))
        ) : (
          <Text size="sm">No positions added</Text>
        )}
        {form.errors.positions && <Input.Error>{form.errors.positions}</Input.Error>}
        <Group>
          <Button
            ref={addPositionRef}
            variant="default"
            onClick={() => form.insertListItem('positions', createPosition())}
          >
            Add position
          </Button>
        </Group>
      </Stack>
    </Stack>
  );
}

import { act, render, screen, userEvent, within } from '@test-utils';
import { Notifications, notifications } from '@mantine/notifications';
import { JobApplicationForm } from './JobApplicationForm';

type User = ReturnType<typeof userEvent.setup>;

function renderForm(onSubmit = jest.fn()) {
  const user = userEvent.setup({ advanceTimers: jest.advanceTimersByTime });
  render(
    <>
      <Notifications />
      <JobApplicationForm onSubmit={onSubmit} />
    </>
  );
  return { user, onSubmit };
}

// The required asterisk is part of the label text, the accessible name leaves it out
const field = (name: string) => screen.getByRole('textbox', { name });
// The country dropdown of the phone input repositions itself in a promise after the step rerenders
// with errors or its button gets focus; settling it inside act keeps the update out of the next step
const settle = () => act(async () => {});

async function next(user: User) {
  await user.click(screen.getByRole('button', { name: 'Next' }));
  await settle();
}

async function blur(user: User) {
  await user.tab();
  await settle();
}

const back = (user: User) => user.click(screen.getByRole('button', { name: 'Back' }));
const stepButton = (label: string) =>
  screen.getByRole('button', { name: new RegExp(`^\\d? ?${label}$`) });

async function fillPersonal(user: User) {
  await user.type(field('First name'), 'Ada');
  await user.type(field('Last name'), 'Lovelace');
  await user.type(field('Email'), 'ada@example.com');
}

async function pickYears(user: User, start: string, end: string) {
  await user.click(screen.getByRole('button', { name: 'Years' }));
  await user.click(await screen.findByRole('button', { name: start }));
  await user.click(screen.getByRole('button', { name: end }));
  await user.click(screen.getByRole('button', { name: 'Save' }));
}

async function fillExperience(user: User) {
  await user.type(field('Current title'), 'Analyst');
  await user.type(field('Years of experience'), '7');
  await user.type(field('Company'), 'Analytical Engines');
  await user.type(field('Title'), 'Programmer');
  await pickYears(user, '2021', '2024');
}

async function pickStartDate(user: User, day: string) {
  await user.click(screen.getByRole('button', { name: 'Earliest start date' }));
  await user.click(await screen.findByRole('button', { name: day }));
  await user.click(screen.getByRole('button', { name: 'Save' }));
}

async function fillAvailability(user: User) {
  await pickStartDate(user, '20 October 2026');
  await user.type(field('Expected salary'), '120000');
  await user.click(screen.getByRole('radio', { name: 'Hybrid' }));
  await user.type(field('Notes'), 'Prefers mornings');
}

async function goToReview(user: User) {
  await fillPersonal(user);
  await next(user);
  await fillExperience(user);
  await next(user);
  await fillAvailability(user);
  await next(user);
}

beforeEach(() => {
  jest.useFakeTimers({ now: new Date(2026, 9, 17, 12), advanceTimers: true });
});

afterEach(() => {
  notifications.clean();
  jest.useRealTimers();
});

describe('personal step', () => {
