import { PhoneInput, SimpleGrid, Stack, TextInput } from '@mantine/core';
import type { JobApplicationFormType } from './types';

export function PersonalStep({ form }: { form: JobApplicationFormType }) {
  const phoneProps = form.getInputProps('phone');

  return (
    <Stack>
      <SimpleGrid cols={{ base: 1, sm: 2 }}>
        <TextInput
          label="First name"
          placeholder="First name"
          withAsterisk
          {...form.getInputProps('firstName')}
        />
        <TextInput
          label="Last name"
          placeholder="Last name"
          withAsterisk
          {...form.getInputProps('lastName')}
        />
      </SimpleGrid>
      <TextInput
        type="email"
        label="Email"
        placeholder="you@example.com"
        withAsterisk
        {...form.getInputProps('email')}
      />
      <PhoneInput
        label="Phone"
        placeholder="Phone"
        defaultCountry="us"
        {...phoneProps}
        onChange={(value, details) => {
          phoneProps.onChange(value);
          // The review step shows the number the way the input displays it, not the raw value
          form.setFieldValue('phoneDisplay', details.formattedValue);
        }}
      />
